export function NameField({ value, error }) {
  const id = "display-name";
  return (
    <>
      <label htmlFor={id}>Display name</label>
      <input
        id={id}
        className={error ? "field field--error" : "field"}
        defaultValue={value}
        aria-invalid={Boolean(error)}
        aria-describedby={error ? `${id}-error` : undefined}
      />
      {error && <p id={`${id}-error`} style={{ color: "#b91c1c" }}>{error}</p>}
      <p>Preview: {value.trim() || "(empty)"}</p>
    </>
  );
}
